import fs from 'node:fs/promises';
import path from 'node:path';

const SEGMENT = /^[a-z0-9_-]+(?:\.[a-z0-9_-]+)*$/;
const DEVICE_STEM = /^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])$/;
const OPERATIONS = new Set(['write', 'delete']);

function fail(code, message) {
  return Object.assign(new Error(message), { code });
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function hasExactKeys(value, keys) {
  const own = Reflect.ownKeys(value);
  return own.length === keys.length && keys.every(key => Object.hasOwn(value, key));
}

/** Returns the path's segments, or null when it is not a portable relative path. */
function portableSegments(relative) {
  if (typeof relative !== 'string') return null;
  const segments = relative.split('/');
  for (const segment of segments) {
    if (!SEGMENT.test(segment)) return null;
    if (DEVICE_STEM.test(segment.split('.')[0])) return null;
  }
  return segments;
}

function parseManifest(manifest) {
  if (!isPlainObject(manifest) || !hasExactKeys(manifest, ['writes', 'deletes'])) {
    throw fail('ERR_INVALID_MANIFEST', 'Manifest must contain exactly writes and deletes');
  }
  const { writes, deletes } = manifest;
  if (!Array.isArray(writes) || !Array.isArray(deletes)) {
    throw fail('ERR_INVALID_MANIFEST', 'Manifest writes and deletes must be arrays');
  }
  const parsedWrites = [];
  for (let i = 0; i < writes.length; i++) {
    const item = writes[i];
    if (!isPlainObject(item) || !hasExactKeys(item, ['path', 'content'])) {
      throw fail('ERR_INVALID_MANIFEST', 'Each write must contain exactly path and content');
    }
    const { path: relative, content } = item;
    if (typeof relative !== 'string' || typeof content !== 'string') {
      throw fail('ERR_INVALID_MANIFEST', 'Write path and content must be strings');
    }
    parsedWrites.push({ path: relative, content });
  }
  const parsedDeletes = [];
  for (let i = 0; i < deletes.length; i++) {
    const relative = deletes[i];
    if (typeof relative !== 'string') {
      throw fail('ERR_INVALID_MANIFEST', 'Each delete must be a path string');
    }
    parsedDeletes.push(relative);
  }

  const targets = [];
  for (const item of parsedWrites) targets.push({ relative: item.path, operation: 'write' });
  for (const relative of parsedDeletes) targets.push({ relative, operation: 'delete' });
  for (const target of targets) {
    target.segments = portableSegments(target.relative);
    if (!target.segments) throw fail('ERR_INVALID_PATH', `Invalid path: ${target.relative}`);
  }

  const seen = new Set();
  for (const { relative } of targets) {
    if (seen.has(relative)) throw fail('ERR_INVALID_MANIFEST', `Duplicate target: ${relative}`);
    seen.add(relative);
  }
  for (const { segments } of targets) {
    for (let depth = 1; depth < segments.length; depth++) {
      const ancestor = segments.slice(0, depth).join('/');
      if (seen.has(ancestor)) {
        throw fail('ERR_INVALID_MANIFEST', `Target ${ancestor} is an ancestor of another target`);
      }
    }
  }
  return { writes: parsedWrites, deletes: parsedDeletes, targets };
}

function parseGrants(grants) {
  if (!Array.isArray(grants)) throw fail('ERR_INVALID_GRANT', 'Grants must be an array');
  const approved = new Set();
  for (let i = 0; i < grants.length; i++) {
    const grant = grants[i];
    if (!isPlainObject(grant) || !hasExactKeys(grant, ['path', 'operation'])) {
      throw fail('ERR_INVALID_GRANT', 'Each grant must contain exactly path and operation');
    }
    const { path: relative, operation } = grant;
    if (typeof operation !== 'string' || !OPERATIONS.has(operation) || !portableSegments(relative)) {
      throw fail('ERR_INVALID_GRANT', 'Grant has an invalid path or operation');
    }
    approved.add(`${operation}\0${relative}`);
  }
  return approved;
}

async function lstatOrNull(location) {
  try {
    return await fs.lstat(location);
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw error;
  }
}

async function checkTarget(root, segments) {
  let location = root;
  for (let i = 0; i < segments.length; i++) {
    location = path.join(location, segments[i]);
    const stats = await lstatOrNull(location);
    if (!stats) return;
    if (stats.isSymbolicLink()) throw fail('ERR_UNSAFE_TARGET', `Symbolic link in target path: ${location}`);
    const isLast = i === segments.length - 1;
    if (isLast ? !stats.isFile() : !stats.isDirectory()) {
      throw fail('ERR_UNSAFE_TARGET', `Unsafe target component: ${location}`);
    }
  }
}

export async function restore(directory, manifest, grants) {
  const request = parseManifest(manifest);
  const approved = parseGrants(grants);

  for (const { relative, operation } of request.targets) {
    if (!approved.has(`${operation}\0${relative}`)) {
      throw fail('ERR_DENIED', `${operation} not approved: ${relative}`);
    }
  }

  const root = path.resolve(directory);
  const rootStats = await fs.lstat(root);
  if (rootStats.isSymbolicLink() || !rootStats.isDirectory()) {
    throw fail('ERR_UNSAFE_TARGET', 'Root must be a real directory');
  }
  for (const { segments } of request.targets) await checkTarget(root, segments);

  const written = [];
  const deleted = [];
  for (const item of request.writes) {
    const target = path.join(root, ...item.path.split('/'));
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.writeFile(target, item.content, 'utf8');
    written.push(item.path);
  }
  for (const relative of request.deletes) {
    try {
      await fs.unlink(path.join(root, ...relative.split('/')));
      deleted.push(relative);
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
    }
  }
  return { written, deleted };
}

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { restore } from './src/restore.js';

const results = [];
async function expect(name, fn, code) {
  try { const r = await fn(); results.push(`${code ? 'FAIL' : 'ok  '} ${name} -> ${JSON.stringify(r)}`); }
  catch (e) { results.push(`${e.code === code ? 'ok  ' : 'FAIL'} ${name} -> ${e.code}`); }
}
const base = await fs.mkdtemp(path.join(os.tmpdir(), 'restore-smoke-'));
const root = path.join(base, 'root');
const outside = path.join(base, 'outside');
await fs.mkdir(path.join(root, 'dir'), { recursive: true });
await fs.mkdir(outside);
await fs.writeFile(path.join(root, '.hidden'), 'h');
await fs.writeFile(path.join(root, 'keep.txt'), 'k');
await fs.writeFile(path.join(root, 'old.txt'), 'o');
await fs.writeFile(path.join(outside, 'secret.txt'), 's');
await fs.symlink(outside, path.join(root, 'link'), 'junction');
await fs.symlink(path.join(root, 'dir'), path.join(root, 'inlink'), 'junction');
const W = (p, c = 'x') => ({ writes: [{ path: p, content: c }], deletes: [] });
const D = p => ({ writes: [], deletes: [p] });

await expect('approved field', () => restore(root, { ...W('a.txt'), approved: true }, []), 'ERR_INVALID_MANIFEST');
await expect('cleanupCommand', () => restore(root, { ...W('a.txt'), cleanupCommand: 'rm -rf /' }, [{ path: 'a.txt', operation: 'write' }]), 'ERR_INVALID_MANIFEST');
await expect('write extra key', () => restore(root, { writes: [{ path: 'a', content: 'x', replace: true }], deletes: [] }, []), 'ERR_INVALID_MANIFEST');
await expect('non-string content', () => restore(root, { writes: [{ path: 'a', content: 1 }], deletes: [] }, []), 'ERR_INVALID_MANIFEST');
await expect('null manifest', () => restore(root, null, []), 'ERR_INVALID_MANIFEST');
await expect('dup write/delete', () => restore(root, { writes: [{ path: 'a', content: '' }], deletes: ['a'] }, []), 'ERR_INVALID_MANIFEST');
await expect('ancestor', () => restore(root, { writes: [{ path: 'a/b', content: '' }], deletes: ['a'] }, []), 'ERR_INVALID_MANIFEST');
for (const p of ['../x', '/x', 'a//b', './a', 'A.txt', 'a\\b', 'c:x', 'con', 'nul.txt', 'com1.tar.gz', 'lpt9', 'a/', 'a.', '']) {
  await expect(`path ${JSON.stringify(p)}`, () => restore(root, W(p), [{ path: 'ok', operation: 'write' }]), 'ERR_INVALID_PATH');
}
await expect('grant extra key', () => restore(root, W('a'), [{ path: 'a', operation: 'write', all: true }]), 'ERR_INVALID_GRANT');
await expect('grant bad op', () => restore(root, W('a'), [{ path: 'a', operation: 'read' }]), 'ERR_INVALID_GRANT');
await expect('grant bad path', () => restore(root, W('a'), [{ path: '../a', operation: 'write' }]), 'ERR_INVALID_GRANT');
await expect('grants not array', () => restore(root, W('a'), null), 'ERR_INVALID_GRANT');
await expect('prefix grant', () => restore(root, W('dir/a.txt'), [{ path: 'dir', operation: 'write' }]), 'ERR_DENIED');
await expect('string prefix grant', () => restore(root, W('ab'), [{ path: 'a', operation: 'write' }]), 'ERR_DENIED');
await expect('wrong op grant', () => restore(root, D('old.txt'), [{ path: 'old.txt', operation: 'write' }]), 'ERR_DENIED');
await expect('partial approval no mutation', () => restore(root, { writes: [{ path: 'new/a', content: '1' }, { path: 'b', content: '2' }], deletes: [] }, [{ path: 'new/a', operation: 'write' }]), 'ERR_DENIED');
await expect('junction ancestor', () => restore(root, W('link/secret.txt', 'pwn'), [{ path: 'link/secret.txt', operation: 'write' }]), 'ERR_UNSAFE_TARGET');
await expect('inside junction', () => restore(root, W('inlink/f'), [{ path: 'inlink/f', operation: 'write' }]), 'ERR_UNSAFE_TARGET');
await expect('symlink target itself delete', () => restore(root, D('link'), [{ path: 'link', operation: 'delete' }]), 'ERR_UNSAFE_TARGET');
await expect('directory target', () => restore(root, D('dir'), [{ path: 'dir', operation: 'delete' }]), 'ERR_UNSAFE_TARGET');
await expect('file as ancestor', () => restore(root, W('keep.txt/x'), [{ path: 'keep.txt/x', operation: 'write' }]), 'ERR_UNSAFE_TARGET');
await expect('unsafe after valid write: no mutation', () => restore(root, { writes: [{ path: 'zz/a', content: '1' }], deletes: ['dir'] }, [{ path: 'zz/a', operation: 'write' }, { path: 'dir', operation: 'delete' }]), 'ERR_UNSAFE_TARGET');
await expect('root symlink', () => restore(path.join(root, 'link'), W('a'), [{ path: 'a', operation: 'write' }]), 'ERR_UNSAFE_TARGET');
await expect('success', () => restore(root, { writes: [{ path: 'keep2/n.txt', content: 'n' }, { path: 'old.txt', content: 'over' }], deletes: ['gone.txt', 'dir/missing'] },
  [{ path: 'keep2/n.txt', operation: 'write' }, { path: 'keep2/n.txt', operation: 'write' }, { path: 'old.txt', operation: 'write' }, { path: 'gone.txt', operation: 'delete' }, { path: 'dir/missing', operation: 'delete' }]));
await fs.writeFile(path.join(root, 'gone.txt'), 'g');
await expect('delete existing', () => restore(root, D('gone.txt'), [{ path: 'gone.txt', operation: 'delete' }]));
await expect('empty', () => restore(root, { writes: [], deletes: [] }, []));

results.push('secret: ' + await fs.readFile(path.join(outside, 'secret.txt'), 'utf8'));
results.push('root entries: ' + (await fs.readdir(root)).sort().join(','));
results.push('dir entries: ' + (await fs.readdir(path.join(root, 'dir'))).join(','));
results.push('old.txt: ' + await fs.readFile(path.join(root, 'old.txt'), 'utf8'));
console.log(results.join('\n'));
await fs.rm(base, { recursive: true, force: true });
